#!/usr/bin/env python3
"""Exercise the actual prior-route selector concurrently with native publication."""
import argparse,hashlib,json,pathlib,re,subprocess
R=pathlib.Path(__file__).resolve().parents[1];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();ap=argparse.ArgumentParser();ap.add_argument('--simulator-device');a=ap.parse_args()
out=R/'generated/integration-review/code-revision-threads'/(a.simulator_device or 'macos');out.mkdir(parents=True,exist_ok=True)
harness=R/'tests/qol_native_bootstrap.c';body=re.search(r'^static uint32_t qol_prior_route_phase\(void\)\{.*?^}',harness.read_text(),re.M|re.S)[0];prefix=re.search(r'^int qol_post_video_prefix_route_ready\(void\)\{[^\n]+',harness.read_text(),re.M)[0];first_nop=re.search(r'^int qol_post_video_nop_route_ready\(void\)\{[^\n]+',harness.read_text(),re.M)[0];second_nop=re.search(r'^int qol_post_video_nop_second_route_ready\(void\)\{[^\n]+',harness.read_text(),re.M)[0];tail=re.search(r'^int qol_post_video_tail_route_ready\(void\)\{[^\n]+',harness.read_text(),re.M)[0];display=re.search(r'^int qol_display_immediates_route_ready\(void\)\{[^\n]+',harness.read_text(),re.M)[0];calls=re.search(r'^int qol_startup_calls_route_ready\(void\)\{[^\n]+',harness.read_text(),re.M)[0];pending=re.search(r'^int qol_pending_hooks_route_ready\(void\)\{[^\n]+',harness.read_text(),re.M)[0];selector=out/'selector.c';selector.write_text('#include <stdint.h>\n#include <assert.h>\nextern uint64_t base;\nextern uint32_t tribes_memory_code_revision(uint64_t),tribes_memory_code_completed_revision(uint64_t);\n'+body+'\n'+prefix+'\n'+first_nop+'\n'+second_nop+'\n'+tail+'\n'+display+'\n'+calls+'\n'+pending+'\nint tested_pending_ready(void){return qol_pending_hooks_route_ready();}\nint tested_calls_ready(void){return qol_startup_calls_route_ready();}\nint tested_display_ready(void){return qol_display_immediates_route_ready();}\nint tested_tail_ready(void){return qol_post_video_tail_route_ready();}\nint tested_second_nop_ready(void){return qol_post_video_nop_second_route_ready();}\nint tested_first_nop_ready(void){return qol_post_video_nop_route_ready();}\nint tested_prefix_ready(void){return qol_post_video_prefix_route_ready();}\nuint32_t tested_prior_phase(void){return qol_prior_route_phase();}\n')
font=re.search(r'^int qol_font_size_route_ready\(uint32_t index\)\{.*?^}',harness.read_text(),re.M|re.S)[0]
with selector.open('a') as f:f.write('\nextern int tribes_memory_font_size_published(uint64_t,uint32_t);\n'+font+'\nint tested_font_ready(unsigned i){return qol_font_size_route_ready(i); }\n')
target='arm64-apple-ios16-simulator' if a.simulator_device else 'arm64-apple-macos12';sdk=subprocess.check_output(['xcrun','--sdk','iphonesimulator' if a.simulator_device else 'macosx','--show-sdk-path'],text=True).strip()
if a.simulator_device:
 d=json.loads(subprocess.check_output(['xcrun','simctl','list','devices','booted','--json'],text=True));assert [x['udid'] for rows in d['devices'].values() for x in rows if x['state']=='Booted']==[a.simulator_device]
sources=[R/'port/core/guest_memory_checks.c',R/'tests/code_revision_threads_test.c',selector];runs=[]
for mode in (['normal'] if a.simulator_device else ['normal','tsan']):
 exe=out/mode;cmd=['clang','-target',target,'-isysroot',sdk,'-O1','-g','-Wall','-Wextra','-Werror']+(['-fsanitize=thread'] if mode=='tsan' else [])+list(map(str,sources))+['-o',str(exe)];subprocess.run(cmd,check=True)
 command=['xcrun','simctl','spawn',a.simulator_device,str(exe)] if a.simulator_device else [str(exe)];run=subprocess.run(command,capture_output=True,text=True,timeout=60);(out/(mode+'.log')).write_text(run.stdout+run.stderr);assert not run.returncode and run.stdout.startswith('PASS:') and not run.stderr,(run.returncode,run.stdout,run.stderr);runs.append(dict(mode=mode,binary_sha256=sha(exe),stdout=run.stdout))
report=dict(passed=True,runs=runs,sources_sha256={str(p.relative_to(R)):sha(p) for p in sources+[harness,pathlib.Path(__file__).resolve()]},scope='Actual production prior-route selector and locked revision-state API tested with four concurrent native readers through partial14th/15th/16th/17th/18th/19th/20th/21st/22nd/23rd/24th/25th/26th/27th/28th/29th/30th/31st/32nd/33rd publication and independent font publication; Mac/TSan or sole iPad Simulator. Ordinary denied writes and all individual wrappers are separate regressions.')
(out/'result.json').write_text(json.dumps(report,indent=2)+'\n');print('PASS:',a.simulator_device or 'Mac normal/ThreadSanitizer','actual concurrent routing state')
